<template><div class="page"><a-page-header title="下载任务" extra=""><template #extra><a-button @click="load">刷新</a-button></template></a-page-header><a-row :gutter="16"><a-col :xs="24" :lg="8" v-for="task in tasks" :key="task.id"><TaskCard :task="task" @action="action(task.id,$event)" /></a-col></a-row><a-empty v-if="!tasks.length" description="暂无下载任务" /><a-modal v-model:open="logsOpen" title="下载任务日志" :footer="null"><a-spin :spinning="logsLoading"><a-timeline v-if="events.length"><a-timeline-item v-for="event in events" :key="event.id" :color="event.kind === 'failed' || event.kind === 'interrupted' ? 'red' : undefined"><a-typography-text>{{ event.message }}</a-typography-text><br /><a-typography-text type="secondary">{{ new Date(event.createdAt).toLocaleString() }}</a-typography-text></a-timeline-item></a-timeline><a-empty v-else description="暂无事件记录" /></a-spin></a-modal></div></template>
<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'; import { message } from 'ant-design-vue'; import TaskCard from '../../components/TaskCard.vue'; import { api } from '../../services/api'; import type { Task, TaskEvent } from '../../types/api'
const tasks=ref<Task[]>([]); const events=ref<TaskEvent[]>([]); const logsOpen=ref(false); const logsLoading=ref(false); let timer:number|undefined
async function load(){tasks.value=await api.tasks()}; async function action(id:string,value:string){if(value==='logs'){logsOpen.value=true;logsLoading.value=true;try{events.value=await api.taskEvents(id)}catch(e){message.error(e instanceof Error?e.message:'读取日志失败')}finally{logsLoading.value=false}return}if(value==='delete'){await api.deleteTask(id);message.success('任务记录已删除')}else{await api.taskAction(id,value);message.success(value==='resume'?'已继续任务':value==='pause'?'已暂停任务':'已取消任务')}await load()}
onMounted(async()=>{await load();timer=window.setInterval(load,2500)});onUnmounted(()=>window.clearInterval(timer))
</script>
